```cpp
struct ShapeQueryContext {
    PhysicsShape* self;
    ShapeQueryResult* results;
    int maxResults;
    int count;
};

static void shapeQueryCallback(cpShape* shape, cpContactPointSet* points, void* data)
{
    auto* ctx = (ShapeQueryContext*)data;
    PhysicsShape* ps = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
    if (ps == nullptr || ps == ctx->self) return;
    // dedupe: shape (edge box) may have multiple cpShapes
    for (int i = 0; i < ctx->count; ++i)
        if (ctx->results[i].shape == ps) return;
    if (ctx->count >= ctx->maxResults) return;
    ShapeQueryResult& r = ctx->results[ctx->count++];
    r.shape = ps;
    r.normal = PhysicsHelper::cpv2point(points->normal);
    r.pointCount = points->count;
    r.depth = 0.0f;
    for (int i = 0; i < points->count && i < 4; ++i)
    {
        r.contactPoints[i] = PhysicsHelper::cpv2point(points->points[i].pointA);
        float d = PhysicsHelper::cpfloat2float(-points->points[i].distance);
        if (d > r.depth) r.depth = d;
    }
}

int PhysicsShapeQuery::shapeQuery(PhysicsShape* shape, ShapeQueryResult* results, int maxResults)
{
    if (!_initialized || shape == nullptr || results == nullptr || maxResults <= 0) return 0;
    ShapeQueryContext ctx{shape, results, maxResults, 0};
    for (cpShape* cp : shape->_cpShapes)
    {
        if (cpShapeGetSpace(cp) == nullptr)
            cpShapeUpdate(cp, cpBodyGetTransform(cpShapeGetBody(cp)));
        cpSpaceShapeQuery(_space, cp, shapeQueryCallback, &ctx);
    }
    return ctx.count;
}
